app.js:(
/* WhatsApp Agent PAS-6.0 | Application Logic | Port 12352 */
class WhatsAppDashboard {
  constructor(config) {
    this.config = config;
    this.state = {
      connected: false,
      qrVisible: false,
      conversations: [],
      contacts: [],
      templates: [],
      media: [],
      webhooks: [],
      analytics: {},
      selectedConversation: null,
      metrics: {
        sent: 0,
        received: 0,
        pending: 0,
        failed: 0,
        contacts: 0,
        templates: 0,
      },
    };
    this.refreshInterval = null;
  }

  async init() {
    console.log(
      `🟢 WhatsApp Agent Dashboard v${this.config.agent.version} initializing...`,
    );
    this.bindNavigation();
    this.bindActions();
    this.bindModals();
    await this.checkHealth();
    this.startAutoRefresh();
    this.showSection("overview");
    console.log("✅ Dashboard ready");
  }

  bindNavigation() {
    document.querySelectorAll(".nav-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        const section = btn.dataset.section;
        if (section) this.showSection(section);
      });
    });
  }

  showSection(sectionId) {
    document
      .querySelectorAll(".nav-btn")
      .forEach((b) => b.classList.remove("active"));
    document
      .querySelectorAll(".section")
      .forEach((s) => s.classList.remove("active"));
    document
      .querySelector(`.nav-btn[data-section="${sectionId}"]`)
      ?.classList.add("active");
    document.getElementById(sectionId)?.classList.add("active");
    this.loadSectionData(sectionId);
  }

  async loadSectionData(section) {
    switch (section) {
      case "overview":
        await this.loadOverview();
        break;
      case "inbox":
        await this.loadConversations();
        break;
      case "contacts":
        await this.loadContacts();
        break;
      case "media":
        await this.loadMedia();
        break;
      case "templates":
        await this.loadTemplates();
        break;
      case "webhooks":
        await this.loadWebhooks();
        break;
      case "analytics":
        await this.loadAnalytics();
        break;
    }
  }

  bindActions() {
    document
      .getElementById("sendMessageBtn")
      ?.addEventListener("click", () => this.showComposeModal());
    document
      .getElementById("refreshBtn")
      ?.addEventListener("click", () => this.checkHealth());
    document
      .getElementById("syncContactsBtn")
      ?.addEventListener("click", () => this.syncContacts());
    document
      .getElementById("showQrBtn")
      ?.addEventListener("click", () => this.showQRCode());
    document
      .getElementById("testApiBtn")
      ?.addEventListener("click", () => this.testApi());
    document
      .getElementById("addContactBtn")
      ?.addEventListener("click", () => this.showAddContactModal());
    document
      .getElementById("newTemplateBtn")
      ?.addEventListener("click", () => this.showNewTemplateModal());
    document
      .getElementById("registerWebhookBtn")
      ?.addEventListener("click", () => this.showWebhookModal());

    // Quick Actions
    document.querySelectorAll(".action-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        const action = btn.dataset.action;
        if (action && typeof this[action] === "function") this[action]();
      });
    });

    // Capability Cards
    document.querySelectorAll(".capability-card").forEach((card) => {
      card.addEventListener("click", () => {
        const capability = card.dataset.capability;
        this.executeCapability(capability);
      });
    });
  }

  bindModals() {
    document.querySelectorAll(".modal-close").forEach((btn) => {
      btn.addEventListener("click", () => this.closeModals());
    });
    document.querySelectorAll(".modal").forEach((modal) => {
      modal.addEventListener("click", (e) => {
        if (e.target === modal) this.closeModals();
      });
    });

    // Compose Modal
    document
      .getElementById("sendComposeBtn")
      ?.addEventListener("click", () => this.sendComposedMessage());
    document
      .getElementById("attachMediaBtn")
      ?.addEventListener("click", () => this.attachMedia());
  }

  closeModals() {
    document
      .querySelectorAll(".modal")
      .forEach((m) => m.classList.remove("active"));
  }

  // ==================== API CALLS ====================
  async apiCall(endpoint, method = "GET", data = null) {
    try {
      const url = `${this.config.agent.baseUrl}${endpoint}`;
      const options = {
        method,
        headers: { "Content-Type": "application/json" },
        timeout: this.config.api.timeout,
      };
      if (data) options.body = JSON.stringify(data);
      const response = await fetch(url, options);
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return await response.json();
    } catch (error) {
      console.error(`API Error [${endpoint}]:`, error);
      return { error: error.message };
    }
  }

  async checkHealth() {
    const status = await this.apiCall(this.config.api.endpoints.health);
    this.state.connected = !status.error && status.status === "ok";
    this.updateConnectionStatus();
    if (this.state.connected) {
      this.showToast("WhatsApp verbunden", "success");
    }
    return status;
  }

  updateConnectionStatus() {
    const badge = document.querySelector(".status-badge");
    const text = document.querySelector(".status-text");
    if (this.state.connected) {
      badge?.classList.add("online");
      if (text) text.textContent = "Connected";
    } else {
      badge?.classList.remove("online");
      if (text) text.textContent = "Disconnected";
    }
  }

  // ==================== OVERVIEW ====================
  async loadOverview() {
    const [health, status, stats] = await Promise.all([
      this.apiCall(this.config.api.endpoints.health),
      this.apiCall(this.config.api.endpoints.accountStatus),
      this.apiCall(this.config.api.endpoints.messageStats),
    ]);

    if (!stats.error) {
      this.updateMetric("msgSent", stats.sent || 0);
      this.updateMetric("msgReceived", stats.received || 0);
      this.updateMetric("msgPending", stats.pending || 0);
      this.updateMetric("msgDelivered", stats.delivered || 0);
      this.updateMetric("contactCount", stats.contacts || 0);
      this.updateMetric("templateCount", stats.templates || 0);
    }
  }

  updateMetric(id, value) {
    const el = document.getElementById(id);
    if (el)
      el.textContent =
        typeof value === "number" ? value.toLocaleString("de-DE") : value;
  }

  // ==================== INBOX ====================
  async loadConversations() {
    const result = await this.apiCall(this.config.api.endpoints.conversations);
    if (!result.error && result.conversations) {
      this.state.conversations = result.conversations;
      this.renderConversationList();
    }
  }

  renderConversationList() {
    const container = document.getElementById("conversationList");
    if (!container) return;

    if (this.state.conversations.length === 0) {
      container.innerHTML = '<div class="loading">Keine Konversationen</div>';
      return;
    }

    container.innerHTML = this.state.conversations
      .map(
        (conv) => `
            <div class="conversation-item ${conv.id === this.state.selectedConversation ? "active" : ""}"
                 data-id="${conv.id}" onclick="dashboard.selectConversation('${conv.id}')">
                <div class="conv-avatar">${conv.name?.charAt(0) || "?"}</div>
                <div class="conv-info">
                    <div class="conv-name">${conv.name || conv.phone}</div>
                    <div class="conv-preview">${conv.lastMessage || ""}</div>
                </div>
                <div class="conv-time">${conv.time || ""}</div>
            </div>
        `,
      )
      .join("");
  }

  async selectConversation(convId) {
    this.state.selectedConversation = convId;
    this.renderConversationList();
    await this.loadMessages(convId);
  }

  async loadMessages(convId) {
    const result = await this.apiCall(
      `${this.config.api.endpoints.conversationHistory}?id=${convId}`,
    );
    if (!result.error && result.messages) {
      this.renderMessages(result.messages);
    }
  }

  renderMessages(messages) {
    const container = document.getElementById("messageList");
    if (!container) return;

    container.innerHTML = messages
      .map(
        (msg) => `
            <div class="message ${msg.fromMe ? "outgoing" : "incoming"}">
                <div class="message-text">${msg.text}</div>
                <div class="message-time">${msg.time || ""}</div>
            </div>
        `,
      )
      .join("");
    container.scrollTop = container.scrollHeight;
  }

  // ==================== CONTACTS ====================
  async loadContacts() {
    const result = await this.apiCall(this.config.api.endpoints.contacts);
    if (!result.error && result.contacts) {
      this.state.contacts = result.contacts;
      this.renderContacts();
    }
  }

  renderContacts() {
    const container = document.getElementById("contactList");
    if (!container) return;

    if (this.state.contacts.length === 0) {
      container.innerHTML = '<div class="loading">Keine Kontakte</div>';
      return;
    }

    container.innerHTML = this.state.contacts
      .map(
        (contact) => `
            <div class="contact-item" data-phone="${contact.phone}">
                <div class="contact-avatar">${contact.name?.charAt(0) || "📱"}</div>
                <div class="contact-info">
                    <div class="contact-name">${contact.name || "Unknown"}</div>
                    <div class="contact-phone">${contact.phone}</div>
                </div>
                <button class="btn btn-sm btn-primary" onclick="dashboard.sendToContact('${contact.phone}')">💬</button>
            </div>
        `,
      )
      .join("");
  }

  async syncContacts() {
    this.showToast("Kontakte synchronisieren...", "info");
    const result = await this.apiCall(
      this.config.api.endpoints.syncContacts,
      "POST",
    );
    if (!result.error) {
      this.showToast(
        `${result.synced || 0} Kontakte synchronisiert`,
        "success",
      );
      await this.loadContacts();
    } else {
      this.showToast("Sync fehlgeschlagen", "error");
    }
  }

  sendToContact(phone) {
    document.getElementById("composeRecipient").value = phone;
    this.showComposeModal();
  }

  // ==================== SEND MESSAGE ====================
  showComposeModal() {
    document.getElementById("composeModal")?.classList.add("active");
  }

  async sendComposedMessage() {
    const recipient = document.getElementById("composeRecipient")?.value;
    const message = document.getElementById("composeMessage")?.value;

    if (!recipient || !message) {
      this.showToast("Empfänger und Nachricht erforderlich", "warning");
      return;
    }

    this.showToast("Sende Nachricht...", "info");
    const result = await this.apiCall(
      this.config.api.endpoints.sendMessage,
      "POST",
      {
        to: recipient,
        message: message,
      },
    );

    if (!result.error) {
      this.showToast("Nachricht gesendet! ✅", "success");
      this.closeModals();
      document.getElementById("composeRecipient").value = "";
      document.getElementById("composeMessage").value = "";
    } else {
      this.showToast("Senden fehlgeschlagen", "error");
    }
  }

  // ==================== MEDIA ====================
  async loadMedia() {
    const result = await this.apiCall(this.config.api.endpoints.mediaGallery);
    if (!result.error && result.media) {
      this.state.media = result.media;
      this.renderMediaGallery();
    }
  }

  renderMediaGallery() {
    const container = document.getElementById("mediaGallery");
    if (!container) return;

    if (this.state.media.length === 0) {
      container.innerHTML = '<div class="loading">Keine Medien</div>';
      return;
    }

    container.innerHTML = this.state.media
      .map(
        (item) => `
            <div class="media-item" data-id="${item.id}" onclick="dashboard.viewMedia('${item.id}')">
                ${item.type === "image" ? "🖼️" : item.type === "video" ? "🎬" : item.type === "audio" ? "🎵" : "📄"}
            </div>
        `,
      )
      .join("");
  }

  showMediaModal() {
    document.getElementById("mediaModal")?.classList.add("active");
  }

  attachMedia() {
    document.getElementById("mediaFileInput")?.click();
  }

  // ==================== TEMPLATES ====================
  async loadTemplates() {
    const result = await this.apiCall(this.config.api.endpoints.templates);
    if (!result.error && result.templates) {
      this.state.templates = result.templates;
      this.renderTemplates();
    }
  }

  renderTemplates() {
    const container = document.getElementById("templatesGrid");
    if (!container) return;

    if (this.state.templates.length === 0) {
      container.innerHTML = '<div class="loading">Keine Templates</div>';
      return;
    }

    container.innerHTML = this.state.templates
      .map(
        (tpl) => `
            <div class="template-card">
                <div class="template-header">
                    <span class="template-name">${tpl.name}</span>
                    <span class="template-status ${tpl.status}">${tpl.status}</span>
                </div>
                <div class="template-content">${tpl.content}</div>
                <div class="template-actions">
                    <button class="btn btn-sm btn-primary" onclick="dashboard.useTemplate('${tpl.id}')">Verwenden</button>
                    <button class="btn btn-sm btn-secondary" onclick="dashboard.editTemplate('${tpl.id}')">Bearbeiten</button>
                </div>
            </div>
        `,
      )
      .join("");
  }

  showTemplateModal() {
    document.getElementById("templateModal")?.classList.add("active");
  }

  showNewTemplateModal() {
    document.getElementById("newTemplateModal")?.classList.add("active");
  }

  async useTemplate(templateId) {
    const template = this.state.templates.find((t) => t.id === templateId);
    if (template) {
      document.getElementById("composeMessage").value = template.content;
      this.showComposeModal();
    }
  }

  // ==================== WEBHOOKS ====================
  async loadWebhooks() {
    const result = await this.apiCall(this.config.api.endpoints.webhooks);
    if (!result.error && result.webhooks) {
      this.state.webhooks = result.webhooks;
      this.renderWebhooks();
    }
  }

  renderWebhooks() {
    const container = document.getElementById("webhookList");
    if (!container) return;

    if (this.state.webhooks.length === 0) {
      container.innerHTML =
        '<div class="loading">Keine Webhooks registriert</div>';
      return;
    }

    container.innerHTML = this.state.webhooks
      .map(
        (wh) => `
            <div class="webhook-item">
                <span class="webhook-url">${wh.url}</span>
                <span class="webhook-events">${wh.events?.join(", ") || "all"}</span>
                <button class="btn btn-sm btn-secondary" onclick="dashboard.deleteWebhook('${wh.id}')">🗑️</button>
            </div>
        `,
      )
      .join("");
  }

  showWebhookModal() {
    document.getElementById("webhookModal")?.classList.add("active");
  }

  async registerWebhook() {
    const url = document.getElementById("webhookUrl")?.value;
    const events = Array.from(
      document.querySelectorAll(".webhook-event:checked"),
    ).map((cb) => cb.value);

    if (!url) {
      this.showToast("URL erforderlich", "warning");
      return;
    }

    const result = await this.apiCall(
      this.config.api.endpoints.webhookRegister,
      "POST",
      { url, events },
    );
    if (!result.error) {
      this.showToast("Webhook registriert", "success");
      this.closeModals();
      await this.loadWebhooks();
    } else {
      this.showToast("Registrierung fehlgeschlagen", "error");
    }
  }

  async deleteWebhook(id) {
    const result = await this.apiCall(
      `${this.config.api.endpoints.webhookDelete}?id=${id}`,
      "DELETE",
    );
    if (!result.error) {
      this.showToast("Webhook gelöscht", "success");
      await this.loadWebhooks();
    }
  }

  // ==================== ANALYTICS ====================
  async loadAnalytics() {
    const result = await this.apiCall(this.config.api.endpoints.analytics);
    if (!result.error) {
      this.state.analytics = result;
      this.renderAnalytics();
    }
  }

  renderAnalytics() {
    // Update analytics displays
    const data = this.state.analytics;
    if (data.daily) {
      this.updateMetric("analyticsSent", data.daily.sent || 0);
      this.updateMetric("analyticsReceived", data.daily.received || 0);
      this.updateMetric(
        "analyticsDeliveryRate",
        `${data.daily.deliveryRate || 0}%`,
      );
      this.updateMetric("analyticsReadRate", `${data.daily.readRate || 0}%`);
    }
  }

  // ==================== QR CODE ====================
  async showQRCode() {
    const result = await this.apiCall(this.config.api.endpoints.qrCode);
    if (!result.error && result.qr) {
      document.getElementById("qrCodeImage").src = result.qr;
      document.getElementById("qrModal")?.classList.add("active");
    } else {
      this.showToast("QR-Code nicht verfügbar", "warning");
    }
  }

  // ==================== API CONSOLE ====================
  async testApi() {
    const endpoint = document.getElementById("apiEndpoint")?.value || "/health";
    const method = document.getElementById("apiMethod")?.value || "GET";
    let body = null;

    if (method !== "GET") {
      const bodyText = document.getElementById("apiBody")?.value;
      if (bodyText) {
        try {
          body = JSON.parse(bodyText);
        } catch (e) {
          this.showToast("Ungültiges JSON", "error");
          return;
        }
      }
    }

    const result = await this.apiCall(endpoint, method, body);
    document.getElementById("apiResponse").textContent = JSON.stringify(
      result,
      null,
      2,
    );
  }

  // ==================== CAPABILITIES ====================
  executeCapability(capabilityId) {
    const capability = this.config.capabilities.find(
      (c) => c.id === capabilityId,
    );
    if (!capability) return;

    switch (capabilityId) {
      case "incoming_messages":
        this.showSection("inbox");
        break;
      case "outgoing_messages":
        this.showComposeModal();
        break;
      case "media_messages":
        this.showMediaModal();
        break;
      case "contact_manager":
        this.showSection("contacts");
        break;
      case "template_api":
        this.showSection("templates");
        break;
      case "webhook_listener":
        this.showSection("webhooks");
        break;
      case "conversation_history":
        this.showSection("inbox");
        break;
      case "account_health":
        this.checkHealth();
        break;
      default:
        this.showToast(`${capability.name} aktiviert`, "info");
    }
  }

  // ==================== BROADCAST ====================
  showBroadcastModal() {
    document.getElementById("broadcastModal")?.classList.add("active");
  }

  async sendBroadcast() {
    const recipients = document
      .getElementById("broadcastRecipients")
      ?.value.split("\n")
      .filter((r) => r.trim());
    const message = document.getElementById("broadcastMessage")?.value;

    if (recipients.length === 0 || !message) {
      this.showToast("Empfänger und Nachricht erforderlich", "warning");
      return;
    }

    this.showToast(`Broadcast an ${recipients.length} Empfänger...`, "info");

    let success = 0;
    for (const recipient of recipients) {
      const result = await this.apiCall(
        this.config.api.endpoints.sendMessage,
        "POST",
        {
          to: recipient.trim(),
          message: message,
        },
      );
      if (!result.error) success++;
    }

    this.showToast(
      `${success}/${recipients.length} gesendet`,
      success === recipients.length ? "success" : "warning",
    );
    this.closeModals();
  }

  // ==================== UTILITIES ====================
  showToast(message, type = "info") {
    const container = document.getElementById("toastContainer");
    if (!container) return;

    const toast = document.createElement("div");
    toast.className = `toast ${type}`;
    toast.textContent = message;
    container.appendChild(toast);

    setTimeout(() => toast.remove(), 4000);
  }

  startAutoRefresh() {
    this.refreshInterval = setInterval(() => {
      this.checkHealth();
    }, this.config.ui.refreshInterval);
  }

  stopAutoRefresh() {
    if (this.refreshInterval) {
      clearInterval(this.refreshInterval);
      this.refreshInterval = null;
    }
  }

  showAddContactModal() {
    document.getElementById("addContactModal")?.classList.add("active");
  }

  viewMedia(id) {
    this.showToast(`Media ${id} öffnen...`, "info");
  }

  editTemplate(id) {
    this.showToast(`Template ${id} bearbeiten...`, "info");
  }
}

// Initialize on DOM ready
let dashboard;
document.addEventListener("DOMContentLoaded", () => {
  dashboard = new WhatsAppDashboard(WhatsAppConfig);
  dashboard.init();
});
)

style.css:(
/* WhatsApp Agent PAS-6.0 | Green Theme | Port 12352 */
:root {
  --primary: #25d366;
  --primary-dark: #128c7e;
  --primary-light: #5ce68a;
  --secondary: #075e54;
  --accent: #34b7f1;
  --bg-dark: #0a1412;
  --bg-card: #111b18;
  --bg-hover: #1a2a25;
  --bg-input: #0f1c18;
  --success: #25d366;
  --warning: #ffc107;
  --error: #dc3545;
  --info: #34b7f1;
  --text-primary: #e9edef;
  --text-secondary: #8696a0;
  --text-muted: #667781;
  --border-color: #233138;
  --glow: rgba(37, 211, 102, 0.3);
}
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
body {
  font-family: "Segoe UI", system-ui, sans-serif;
  background: linear-gradient(135deg, var(--bg-dark), #050a08);
  color: var(--text-primary);
  min-height: 100vh;
}

.dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 2rem;
  background: var(--secondary);
  border-bottom: 2px solid var(--primary);
}
.header-left {
  display: flex;
  align-items: center;
  gap: 1rem;
}
.logo {
  font-size: 2.5rem;
  filter: drop-shadow(0 0 10px var(--primary));
}
.header-info h1 {
  font-size: 1.4rem;
  color: var(--primary-light);
}
.version {
  color: var(--text-secondary);
  font-size: 0.85rem;
}
.header-right {
  display: flex;
  align-items: center;
  gap: 1rem;
}
.status-badge {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  background: rgba(0, 0, 0, 0.3);
  border-radius: 20px;
}
.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--warning);
  animation: pulse 2s infinite;
}
.status-badge.online .status-dot {
  background: var(--success);
}
@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}
.port-badge {
  background: var(--primary);
  color: var(--bg-dark);
  padding: 0.4rem 0.8rem;
  border-radius: 4px;
  font-weight: 600;
}

.dashboard-nav {
  display: flex;
  gap: 0.5rem;
  padding: 1rem 2rem;
  background: var(--bg-card);
  border-bottom: 1px solid var(--border-color);
  flex-wrap: wrap;
}
.nav-btn {
  padding: 0.6rem 1rem;
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.3s;
}
.nav-btn:hover {
  background: var(--bg-hover);
  border-color: var(--primary);
}
.nav-btn.active {
  background: var(--primary);
  color: var(--bg-dark);
  font-weight: 600;
}

.dashboard-main {
  padding: 2rem;
  max-width: 1800px;
  margin: 0 auto;
}
.section {
  display: none;
}
.section.active {
  display: block;
  animation: fadeIn 0.3s;
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
}
.section-header h2 {
  color: var(--primary-light);
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 1.5rem;
  margin-bottom: 1.5rem;
}
.card h3 {
  color: var(--primary-light);
  margin-bottom: 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--border-color);
}

.metrics-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1rem;
  margin-bottom: 1.5rem;
}
.metric-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 1.5rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  transition: transform 0.3s;
}
.metric-card:hover {
  transform: translateY(-3px);
}
.metric-card.primary {
  border-left: 4px solid var(--primary);
}
.metric-card.success {
  border-left: 4px solid var(--success);
}
.metric-card.warning {
  border-left: 4px solid var(--warning);
}
.metric-card.info {
  border-left: 4px solid var(--info);
}
.metric-icon {
  font-size: 2rem;
}
.metric-value {
  font-size: 1.8rem;
  font-weight: 700;
  display: block;
}
.metric-label {
  color: var(--text-muted);
  font-size: 0.85rem;
}

.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 1rem;
}
.capability-card {
  background: var(--bg-hover);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  padding: 1rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  cursor: pointer;
  transition: all 0.3s;
}
.capability-card:hover {
  border-color: var(--primary);
  box-shadow: 0 0 15px var(--glow);
}
.capability-icon {
  font-size: 1.5rem;
}
.capability-info h4 {
  color: var(--primary-light);
  font-size: 0.9rem;
}
.capability-info p {
  color: var(--text-muted);
  font-size: 0.75rem;
}

.action-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(100px, 1fr));
  gap: 1rem;
}
.action-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  padding: 1rem;
  background: var(--bg-hover);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  color: var(--text-primary);
  cursor: pointer;
  transition: all 0.3s;
}
.action-btn:hover {
  border-color: var(--primary);
  transform: translateY(-3px);
}
.action-icon {
  font-size: 1.5rem;
}

.btn {
  padding: 0.6rem 1.2rem;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-weight: 500;
  transition: all 0.3s;
}
.btn-primary {
  background: var(--primary);
  color: var(--bg-dark);
}
.btn-primary:hover {
  background: var(--primary-light);
  box-shadow: 0 0 20px var(--glow);
}
.btn-secondary {
  background: var(--bg-hover);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}
.btn-lg {
  padding: 1rem 2rem;
  font-size: 1.1rem;
}
.btn-sm {
  padding: 0.4rem 0.8rem;
  font-size: 0.85rem;
}

.form-group {
  margin-bottom: 1rem;
}
.form-group label {
  display: block;
  margin-bottom: 0.5rem;
  color: var(--text-secondary);
}
.form-control {
  width: 100%;
  padding: 0.8rem;
  background: var(--bg-input);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  color: var(--text-primary);
}
.form-control:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 10px var(--glow);
}
textarea.form-control {
  min-height: 80px;
  resize: vertical;
}

/* Inbox Layout */
.inbox-container {
  display: grid;
  grid-template-columns: 350px 1fr;
  gap: 1rem;
  height: 600px;
}
.conversation-list {
  background: var(--bg-card);
  border-radius: 12px;
  overflow-y: auto;
}
.conversation-item {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1rem;
  border-bottom: 1px solid var(--border-color);
  cursor: pointer;
}
.conversation-item:hover {
  background: var(--bg-hover);
}
.conversation-item.active {
  background: var(--primary);
  color: var(--bg-dark);
}
.conv-avatar {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background: var(--secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}
.conv-info {
  flex: 1;
}
.conv-name {
  font-weight: 600;
}
.conv-preview {
  font-size: 0.85rem;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.conv-time {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.message-view {
  background: var(--bg-card);
  border-radius: 12px;
  display: flex;
  flex-direction: column;
}
.message-header {
  padding: 1rem;
  border-bottom: 1px solid var(--border-color);
  font-weight: 600;
  color: var(--primary-light);
}
.message-list {
  flex: 1;
  overflow-y: auto;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.message {
  max-width: 70%;
  padding: 0.8rem 1rem;
  border-radius: 12px;
}
.message.incoming {
  align-self: flex-start;
  background: var(--bg-hover);
}
.message.outgoing {
  align-self: flex-end;
  background: var(--primary);
  color: var(--bg-dark);
}
.message-input-area {
  display: flex;
  gap: 0.5rem;
  padding: 1rem;
  border-top: 1px solid var(--border-color);
}

.contact-list {
  max-height: 500px;
  overflow-y: auto;
  margin-top: 1rem;
}
.contact-item {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.8rem;
  border-bottom: 1px solid var(--border-color);
}
.contact-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--secondary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.templates-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 1rem;
}
.template-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 1.5rem;
}
.template-header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 1rem;
}
.template-name {
  font-weight: 600;
  color: var(--primary-light);
}
.template-status {
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  font-size: 0.75rem;
}
.template-status.approved {
  background: var(--success);
  color: white;
}
.template-status.pending {
  background: var(--warning);
  color: #000;
}
.template-content {
  color: var(--text-secondary);
  font-size: 0.9rem;
}

.media-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 1rem;
}
.media-item {
  aspect-ratio: 1;
  background: var(--bg-hover);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  cursor: pointer;
}
.media-item:hover {
  border: 2px solid var(--primary);
}

.webhook-events {
  margin: 1rem 0;
}
.webhook-events label {
  display: block;
  margin: 0.5rem 0;
  color: var(--text-secondary);
}
.webhook-log {
  max-height: 300px;
  overflow-y: auto;
  background: var(--bg-dark);
  padding: 1rem;
  border-radius: 8px;
  font-family: monospace;
  font-size: 0.85rem;
}

.analytics-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 1rem;
}
.chart-container {
  height: 200px;
  background: var(--bg-dark);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

.endpoint-grid {
  display: grid;
  gap: 0.5rem;
}
.endpoint-item {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.8rem;
  background: var(--bg-hover);
  border-radius: 6px;
}
.method {
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 600;
}
.method.get {
  background: var(--success);
  color: white;
}
.method.post {
  background: var(--info);
  color: white;
}
.endpoint-item code {
  flex: 1;
  color: var(--accent);
}

.modal {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.8);
  z-index: 1000;
  align-items: center;
  justify-content: center;
}
.modal.active {
  display: flex;
}
.modal-content {
  background: var(--bg-card);
  border: 1px solid var(--primary);
  border-radius: 16px;
  width: 90%;
  max-width: 600px;
  max-height: 80vh;
  overflow: hidden;
}
.modal-header {
  display: flex;
  justify-content: space-between;
  padding: 1rem;
  background: var(--secondary);
}
.modal-header h3 {
  color: var(--primary-light);
}
.modal-close {
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 1.5rem;
  cursor: pointer;
}
.modal-body {
  padding: 1.5rem;
  overflow-y: auto;
  max-height: 60vh;
}
.modal-body pre {
  background: var(--bg-dark);
  padding: 1rem;
  border-radius: 8px;
  overflow-x: auto;
}
.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 1rem;
  padding: 1rem;
  background: var(--bg-dark);
}

.toast-container {
  position: fixed;
  top: 1rem;
  right: 1rem;
  z-index: 2000;
}
.toast {
  padding: 1rem 1.5rem;
  border-radius: 8px;
  color: white;
  margin-bottom: 0.5rem;
  animation: slideIn 0.3s;
}
.toast.success {
  background: var(--success);
  color: var(--bg-dark);
}
.toast.error {
  background: var(--error);
}
.toast.warning {
  background: var(--warning);
  color: #000;
}
.toast.info {
  background: var(--info);
}
@keyframes slideIn {
  from {
    transform: translateX(100%);
  }
  to {
    transform: translateX(0);
  }
}

.dashboard-footer {
  display: flex;
  justify-content: space-between;
  padding: 1rem 2rem;
  background: var(--secondary);
  color: var(--text-secondary);
  font-size: 0.85rem;
}

.loading {
  text-align: center;
  padding: 2rem;
  color: var(--text-muted);
}

@media (max-width: 768px) {
  .dashboard-header {
    flex-direction: column;
    gap: 1rem;
  }
  .inbox-container {
    grid-template-columns: 1fr;
    height: auto;
  }
}
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-track {
  background: var(--bg-dark);
}
::-webkit-scrollbar-thumb {
  background: var(--primary-dark);
  border-radius: 4px;
}
)

